const aiOutput = items[0].json.output;
const agentData = $('AI Agent2').item.json;
let finalMessageForUser = aiOutput;
let welcomeImageUrl = null;
let bookingData = { booking: false, escalate: false };
let promptTokens = agentData?.response_metadata?.tokenUsage?.promptTokens || agentData?.usage_metadata?.prompt_token_count || 0;
let completionTokens = agentData?.response_metadata?.tokenUsage?.completionTokens || agentData?.usage_metadata?.candidates_token_count || 0;
if (promptTokens === 0 || completionTokens === 0) {
    const ctx = $('Finalize Context').first().json;
    const userMessage = $('Set Prod Mode').first().json.message || "";
    const fullInputText = (ctx.finalSystemPrompt || "") + (ctx.finalKnowledge || "") + userMessage;
    promptTokens = Math.ceil(fullInputText.length / 4);
    completionTokens = Math.ceil((aiOutput || "").length / 4);
}
let totalTokens = promptTokens + completionTokens;
try {
    if (!aiOutput) throw new Error("Output kosong");
    const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
        let jsonString = jsonMatch[0];
        jsonString = jsonString.replace(/^json\s*/i, "").replace(/$/i, "");
        jsonString = jsonString.replace(/\\(?!["\\bfnrtu])/g, "\\\\");
        const parsed = JSON.parse(jsonString);
        if (parsed.booking && String(parsed.booking).toLowerCase() === 'true') {
            bookingData.booking = true;
            bookingData.topic = parsed.topic;
            bookingData.clientEmail = parsed.clientEmail;
            let time = parsed.startTime ? parsed.startTime.replace(' ', 'T') : '';
            if (time && time.split(':').length === 2) { time = time.includes('+') ? time.split('+')[0] + ':00+' + time.split('+')[1] : time + ':00'; }
            if (time && !time.includes('+') && !time.endsWith('Z')) time += '+07:00';
            bookingData.startTime = time;
        }
        if (parsed.escalate && String(parsed.escalate).toLowerCase() === 'true') { bookingData.escalate = true; }
        finalMessageForUser = aiOutput.replace(/json[\s\S]*/g, "").trim();
        finalMessageForUser = finalMessageForUser.replace(/\{[\s\S]*\}/g, "").trim();
        finalMessageForUser = finalMessageForUser.replace(/`/g, "").trim();
    }
    const imgMatch = finalMessageForUser.match(/WELCOME_IMAGE_URL:\s*(\S+)/i);
    if (imgMatch && imgMatch[1]) {
        welcomeImageUrl = imgMatch[1].trim();
        finalMessageForUser = finalMessageForUser.replace(/WELCOME_IMAGE_URL:\s*\S+/i, "").trim();
    }
} catch (error) { bookingData.error = error.message; }
return [{ json: { ...bookingData, welcome_image_url: welcomeImageUrl, text_for_wa: finalMessageForUser, output: finalMessageForUser, tokens: { prompt: promptTokens, completion: completionTokens, total: totalTokens } } }];

const input = $input.first().json.body
return {
    json: {
        mode: 'simulation',
        message: input.message,
        sessionId: input.sessionId,
        agentConfig: input.agentConfig 
    }
};

const trigger = $('WAHA Trigger').item.json;
const payload = trigger.payload || {};
let senderId = payload.from || "";
if (payload.author) { senderId = payload.author; }
const message = payload.body || "";
if (!senderId) { throw new Error('Sender ID tidak ditemukan dari WAHA Trigger'); }
return { json: { mode: 'production', message: message, sessionId: senderId, chatId: senderId, agentConfig: null } };

const originalData = $('Merge Inputs').item.json;
const data = items[0].json;
let finalPrompt = "";
let finalKnowledge = "";
let finalFollowup = null;
if (originalData.mode === 'production') {
    finalPrompt = data.system_prompt || "";
    finalKnowledge = data.knowledge || "";
    finalFollowup = data.followup_config || null;
} else {
    finalPrompt = data.agentConfig?.systemInstruction || "";
    finalKnowledge = data.agentConfig?.knowledgeBase || "";
    finalFollowup = data.agentConfig?.followupConfig || null;
}
return { json: { ...originalData, ...data, finalSystemPrompt: finalPrompt, finalKnowledge: finalKnowledge, followupConfig: finalFollowup } };

const ctx = $('Finalize Context').item.json;
const followup = ctx.followupConfig || {};
const delay = Number(followup.delay) || 15;
const unit = followup.unit === 'hours' ? 'hours' : 'minutes';
let text = followup.prompt || "";
text = text.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
return { json: { ...$json, followup_delay_amount: delay, followup_delay_unit: unit, followup_text: text } };
